create table if not exists public.creator_protocol_incidents (id uuid primary key default gen_random_uuid(), constitution_id uuid, severity text not null, incident_type text not null, status text not null default 'open', public_summary text, declared_at timestamptz not null default now(), expires_at timestamptz, policy_version text not null);
create table if not exists public.creator_protocol_public_projections (id uuid primary key default gen_random_uuid(), projection_type text not null, source_type text not null, source_id uuid not null, source_version text not null, public_payload jsonb not null, disputed boolean not null default false, suspended boolean not null default false, revoked boolean not null default false, fresh_until timestamptz, created_at timestamptz not null default now());
create table if not exists public.creator_protocol_audit_events (id uuid primary key default gen_random_uuid(), event_type text not null, actor_type text not null, actor_id uuid, subject_type text not null, subject_id uuid, payload jsonb not null, previous_hash text, event_hash text not null, created_at timestamptz not null default now());
create table if not exists public.creator_protocol_outbox (id uuid primary key default gen_random_uuid(), event_type text not null, aggregate_type text not null, aggregate_id uuid not null, payload jsonb not null, idempotency_key text not null unique, status text not null default 'pending', attempts integer not null default 0, available_at timestamptz not null default now(), created_at timestamptz not null default now());
alter table public.creator_protocol_incidents enable row level security; alter table public.creator_protocol_public_projections enable row level security; alter table public.creator_protocol_audit_events enable row level security; alter table public.creator_protocol_outbox enable row level security;
